import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"Usage & metering","description":"The inverted model — compute runs free in the user's browser (serverless qpu-os); the QPU's content-address cache is the paid, metered service.","frontmatter":{"title":"Usage & metering","description":"The inverted model — compute runs free in the user's browser (serverless qpu-os); the QPU's content-address cache is the paid, metered service.","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"Usage & metering | Millennium Solutions"}],["meta",{"property":"og:description","content":"The inverted model — compute runs free in the user's browser (serverless qpu-os); the QPU's content-address cache is the paid, metered service."}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/usage.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Usage & metering | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"The inverted model — compute runs free in the user's browser (serverless qpu-os); the QPU's content-address cache is the paid, metered service."}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/usage.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/usage.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/usage.html"}]]},"headers":[],"relativePath":"usage.md","filePath":"usage.md"}`),a={name:`usage.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="usage-metering-—-compute-free-cache-paid" tabindex="-1">Usage &amp; metering — compute free, cache paid <a class="header-anchor" href="#usage-metering-—-compute-free-cache-paid" aria-label="Permalink to “Usage &amp; metering — compute free, cache paid”">​</a></h1><blockquote><p><strong>Inverted, and client-side.</strong> The QPU runs as a <strong>serverless qpu-os in the user&#39;s own browser</strong> — the hardware is the <strong>user&#39;s device</strong>, and all computing is <strong>client-side and free</strong>. What is <strong>paid</strong> is the <strong>cache</strong>: the QPU&#39;s content-address store serves a <strong>verified result by its handle</strong> (the 304 involution, O(1)) so the client need not recompute it (O(n)). You pay to <strong>skip the recompute</strong>, never to compute.</p></blockquote><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to “The model”">​</a></h2><ul><li><strong>compute:</strong> client-side, <strong>free</strong> — the qpu-os runs in the browser, serverless; the user&#39;s device is the hardware.</li><li><strong>cache (paid):</strong> the QPU serves a verified answer <strong>by handle</strong> — a hit saves the client a recompute. Metered over <strong>x402</strong> (HTTP 402), per serve (or per second of cache usage).</li><li><strong>unit:</strong> a <strong>handle-serve</strong> — one verified result delivered by its content-address, which would otherwise cost the client <code>recompute(n)</code> locally.</li></ul><h2 id="billing-basis-—-only-where-a-cost-occurs" tabindex="-1">Billing basis — only where a cost occurs <a class="header-anchor" href="#billing-basis-—-only-where-a-cost-occurs" aria-label="Permalink to “Billing basis — only where a cost occurs”">​</a></h2><p>Free is <strong>not a discount</strong>: it is that <strong>no billable cost occurs</strong>. The client computes on their <strong>own device</strong>, so the deposit spends nothing — and the licence (<strong>CC BY-NC-ND</strong>) permits the use. There is nothing to bill. Billing applies <strong>only to a cost the provider actually incurs</strong>: serving the <strong>cache</strong> from its hosted content-address store (and amortising the one-time generation behind a handle). You are billed for a cost the provider incurs, <strong>never for your own free compute</strong>.</p><h2 id="fair-by-construction" tabindex="-1">Fair by construction <a class="header-anchor" href="#fair-by-construction" aria-label="Permalink to “Fair by construction”">​</a></h2><p>The cache charges only when it <strong>saves</strong> work: a handle-serve is O(1) — <code>verify(1) &lt; recompute(n)</code>, sealed (8 correspondence theorems) — against the client&#39;s own <code>recompute(n)</code>. You never pay to recompute; you pay only to <strong>skip</strong> it. The content-address efficiency <em>is</em> the product, and it is why unbounded streams carry no cost until a cache hit is bought.</p><h2 id="the-rate-—-the-quantum-market-benchmark-fetched-live" tabindex="-1">The rate — the quantum-market benchmark, fetched live <a class="header-anchor" href="#the-rate-—-the-quantum-market-benchmark-fetched-live" aria-label="Permalink to “The rate — the quantum-market benchmark, fetched live”">​</a></h2><p>The owner&#39;s chosen rate <strong>policy</strong>: the per-serve price is <strong>the live market rate for the equivalent quantum computation</strong> — what the same job would cost on cloud quantum hardware — <strong>fetched at request time</strong> from a quantum-pricing source (e.g. AWS Braket / Azure Quantum / IonQ published rates; the endpoint is owner-configured, fetched under its terms). It is a <strong>value benchmark</strong>: fetched at quote time, so this page sets <strong>no fixed number</strong> and the deterministic build bakes none.</p><p>The benchmark does <strong>not</strong> change the product. You pay the quantum-market rate for a <strong>verified result delivered classically</strong> — knowing it is classical — because the result is the one a quantum computer would return and you need not own the hardware to get it. <code>isQuantumComputer: false</code> on every response: the market rate is the price of the <strong>answer</strong>, never a claim to the machine.</p><p>Still the owner&#39;s to set (policy = <strong>NEEDS_OWNER</strong>: <em>takes money or sets prices: needs a payment account, a price and terms that only the owner can set</em>):</p><ul><li><strong>pricing API:</strong> <em>(owner-configured)</em> — the endpoint the meter fetches the market rate from, at request time, under its terms; no user data is sent to it.</li><li><strong>payment account:</strong> <em>(unset)</em> — the x402 wallet / Stripe account.</li><li><strong>terms:</strong> <em>(unset)</em> — what a serve entitles, refunds, limits.</li></ul><p>The meter, the live-rate fetch and the x402 gate are the scaffold; <strong>no account is wired.</strong> Configure the pricing API and the account and the provider is live — the code already serves-by-handle, quotes at the market rate, and gates.</p><h2 id="honest-floor" tabindex="-1">Honest floor <a class="header-anchor" href="#honest-floor" aria-label="Permalink to “Honest floor”">​</a></h2><p>The qpu-os is a <strong>classical</strong> engine on the user&#39;s device: browser or client, it computes quantum-<strong>shaped</strong> math, <strong>not</strong> physical quantum behaviour. <strong><code>isQuantumComputer: false</code> regardless of where it runs</strong> — running in the user&#39;s browser does not make it a quantum computer; that is still the CHSH-on-real-hardware leaf (open, <code>/iso-conformance</code>, <code>/chsh-run</code>). You pay for the <strong>cache</strong> — a content-address service — never for quantum hardware. Under <strong>CC BY-NC-ND</strong>, a consumer pays to <em>use</em> the service, not to resell the work.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};